const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let combatView=null;let storage;try{storage=localStorage;}catch{storage={getItem:()=>null,setItem:()=>{throw new Error('Storage unavailable');}};}
const loaded=readSave(storage);let state=loaded.state,starter='sprig',engine,battle=null,busy=false,selectedJournal='sprig',journalFilter='all',lastSave=0,toastTimer,turnTimer,confirmCallback=null,afterConfirm=null,portraitOK=true;
const sound=new IslandAudio();const img=(id,attrs='')=>`<img src="${portraitOK?portrait(id):'./mark.svg'}" alt="${BY_ID[id].name}" ${attrs}>`;
const typePill=(id,override)=>{const type=override||BY_ID[id].type;return `<span class="pill type-${type}" style="color:var(--type)">${TYPES[type].icon} ${TYPES[type].name}</span>`;};
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4300);}
function save(){if(!state)return;const ok=writeSave(state,storage);$('#save-status').textContent=ok?'このブラウザに保存':'保存できません・書き出してね';$('#save-status').style.color=ok?'':'#b45d39';lastSave=Date.now();}
