for(const button of $$('[data-close]'))button.onclick=()=>closeDialog('#'+button.closest('dialog').id);
for(const dialog of $$('dialog'))dialog.addEventListener('close',()=>{if(!$$('dialog[open]').length)engine?.setModal(!$('#welcome').hidden||!!battle);});
